const packs=['spring','summer','autumn','winter'];let pack='spring';document.querySelector('#packs').innerHTML=packs.map((p,i)=>`<button data-pack="${p}" aria-pressed="${i===0}">${p[0].toUpperCase()+p.slice(1)}</button>`).join('');document.querySelector('#packs').onclick=e=>{const b=e.target.closest('[data-pack]');if(!b)return;pack=b.dataset.pack;document.querySelector('main').dataset.bloomAccent=pack;document.querySelector('#name').textContent=pack[0].toUpperCase()+pack.slice(1);document.querySelectorAll('[data-pack]').forEach(x=>x.setAttribute('aria-pressed',x===b));};document.querySelector('#apply').onclick=()=>{try{localStorage.setItem('ob.bloomAccent',pack)}catch(e){}window.dispatchEvent(new CustomEvent('omnibloom:accent-change',{detail:{schema:1,universe:'bloom',accent:pack}}));document.querySelector('#status').textContent='Preview saved · '+pack;};